import {partDefaults} from './part-parameters.js';import {placeOnBreadboard} from './mounting.js';
export const SHIFT_EXAMPLES=[{id:'shift-595',name:'Uno · 74HC595 çift çıkış',tag:'16 bit · latch / Hi-Z'},{id:'shift-165',name:'Uno · 74HC165 paralel giriş',tag:'8 bit · buton / load'},{id:'shift-165-chain',name:'Uno · 74HC165 çift giriş',tag:'16 bit · seri kaskat'}];
export const SHIFT_SOURCES={'shift-595':`void setup(){Serial.begin(115200);for(int p=7;p<=10;p++){pinMode(p,OUTPUT);digitalWrite(p,LOW);}}
void loop(){digitalWrite(10,LOW);shiftOut(8,9,MSBFIRST,0xA5);shiftOut(8,9,MSBFIRST,0x3C);digitalWrite(10,HIGH);Serial.print("595 Q0=");Serial.print(analogRead(A0));Serial.print(" Q7far=");Serial.println(analogRead(A1));delay(250);digitalWrite(7,HIGH);Serial.print("595 OE=HiZ Q7far=");Serial.println(analogRead(A1));delay(250);digitalWrite(7,LOW);}
`,'shift-165':`void setup(){Serial.begin(115200);pinMode(8,OUTPUT);pinMode(9,OUTPUT);pinMode(12,INPUT);digitalWrite(9,LOW);digitalWrite(8,HIGH);}
void loop(){digitalWrite(8,LOW);delayMicroseconds(2);digitalWrite(8,HIGH);uint8_t v=0;for(int i=0;i<8;i++){v=(v<<1)|digitalRead(12);digitalWrite(9,HIGH);digitalWrite(9,LOW);}Serial.print("165 INPUT=");Serial.println(v,HEX);delay(100);}
`};
SHIFT_SOURCES['shift-165-chain']=SHIFT_SOURCES['shift-165'].replace('uint8_t v=0','uint16_t v=0').replace('i<8','i<16');
export function makeShiftProject(base,id){const e=SHIFT_EXAMPLES.find(e=>e.id===id);if(!e)return null;const p=structuredClone(base);p.model=id;p.name=e.name;p.code=SHIFT_SOURCES[id];delete p.firmware;let sequence=p.wires.length;const part=(type,id,params={},x=800,y=380)=>{const c={id,type,x,y,rotation:0,params:{...partDefaults(type),...params}};p.components.push(c);return c;},wire=(from,to,color='#14b8a6')=>p.wires.push({id:'shift'+sequence++,from,to,color,points:[]}),power=id=>{wire('uno:5V',id+':VCC','#ef4444');wire('uno:GND.1',id+':GND','#64748b');};
 if(id==='shift-595'){const c=part('hc595','near');placeOnBreadboard(p,c);part('hc595','far',{},960,330);power('near');power('far');wire('uno:D8','near:SER');wire('near:Q7S','far:SER');for(const i of['near','far']){wire('uno:D9',i+':SRCLK');wire('uno:D10',i+':RCLK');wire('uno:D7',i+':OE');wire('uno:5V',i+':SRCLR','#ef4444');}for(const[i,pin,out]of[['near','Q0','A0'],['far','Q7','A1']]){wire(i+':'+pin,'uno:'+out);part('resistor','pull'+i,{ohms:10000},850,i==='near'?550:610);wire(i+':'+pin,'pull'+i+':1');wire('pull'+i+':2','uno:GND.1','#64748b');}for(let i=0;i<4;i++){part('resistor','r'+i,{ohms:470},850+i*75,220);part('led','l'+i,{color:'red'},850+i*75,160);wire('near:Q'+(i+2),'r'+i+':1');wire('r'+i+':2','l'+i+':A','#ef4444');wire('l'+i+':K','uno:GND.1','#64748b');}p.settings.tracePins=['D8','D9','D10'];}
 else{const c=part('hc165','module');placeOnBreadboard(p,c);power('module');wire('uno:D8','module:PL');wire('uno:D9','module:CLK');wire('uno:D12','module:Q7');wire('uno:GND.1','module:CE','#64748b');wire('uno:GND.1','module:SER','#64748b');for(let i=0;i<8;i++)if(i!==6)wire((0xA5&(1<<i)?'uno:5V':'uno:GND.1'),'module:D'+i,0xA5&(1<<i)?'#ef4444':'#64748b');part('resistor','pull',{ohms:10000},850,550);part('button','input',{},960,480);wire('uno:5V','pull:1','#ef4444');wire('pull:2','module:D6');wire('module:D6','input:1');wire('input:2','uno:GND.1','#64748b');p.settings.tracePins=['D8','D9','D12'];}if(id==='shift-165-chain'){part('hc165','far',{},970,300);power('far');for(const pin of['PL','CLK','CE'])wire('module:'+pin,'far:'+pin);p.wires=p.wires.filter(w=>w.to!=='module:SER');wire('far:Q7','module:SER');wire('uno:GND.1','far:SER','#64748b');for(let i=0;i<8;i++)wire(0x3c&(1<<i)?'uno:5V':'uno:GND.1','far:D'+i,0x3c&(1<<i)?'#ef4444':'#64748b');}p.settings.probe='D9';return p;}
